// startMetricsServer 独立口暴露合并后的 /metrics（与业务端口隔离）。
func startMetricsServer(addr, path string) {
	mux := http.NewServeMux()
	mux.Handle(path, metrics.Handler())
	go func() {
		if err := http.ListenAndServe(addr, mux); err != nil {
			hlog.SystemLogger().Errorf("[metrics] listen %s%s failed: %v", addr, path, err)
		}
	}()
}

func registerMiddleware(h *server.Hertz) {
	//ctx-cache
	h.Use(middleware.ContextCacheMW())

	// JSON id 边界转换：请求体 id 字符串 → 数字（雪花 id 精度）
	h.Use(jsonid.Middleware())

	// pprof
	if conf.GetConf().Server.EnablePprof {
		pprof.Register(h)
	}
	// gzip
	if conf.GetConf().Server.EnableGzip {
		h.Use(gzip.Gzip(gzip.DefaultCompression))
	}

	// x-request-id
	h.Use(requestid.New(requestid.WithCustomHeaderStrKey(consts.RequestHeaderIdKey)))

	// access log
	if conf.GetConf().Server.EnableAccessLog {
		h.Use(accesslog.New())

		// log
		logger := hertzlogrus.NewLogger(
			hertzlogrus.WithHook(
				&logger.RequestIdHook{
					HeaderKey: consts.RequestHeaderIdKey,
				}))

		hlog.SetLogger(logger)
		hlog.SetLevel(conf.LogLevel())
		fileWriter := io.MultiWriter(&lumberjack.Logger{
			Filename:   conf.GetConf().Server.LogFileName,
			MaxSize:    conf.GetConf().Server.LogMaxSize,
			MaxBackups: conf.GetConf().Server.LogMaxBackups,
			MaxAge:     conf.GetConf().Server.LogMaxAge,
		}, os.Stdout)
		hlog.SetOutput(fileWriter)
	}

	// oper log：注册在 requestid/accesslog 之后、recovery 之前（外层），
	// panic 由内层 recovery 捕获并回填 PanicKey，收尾统一分类入队
	h.Use(operlog.MW())

	// recovery
	h.Use(recovery.Recovery(
		recovery.WithRecoveryHandler(func(ctx context.Context, c *app.RequestContext, err interface{}, stack []byte) {
			hlog.SystemLogger().CtxErrorf(ctx, "[Recovery] err=%v\nstack=%s", err, stack)
			c.Set(operlog.PanicKey, &operlog.PanicInfo{Err: err, Stack: stack})
			if customErr, ok := err.(error); ok {
				R.Error(ctx, c, customErr)
				return
			}
			R.Failed(ctx, c, http.StatusInternalServerError, fmt.Errorf("%v", err))
		}),
	))

	// cores
	h.Use(cors.Default())
}
